'use server'

import { createClient } from '@/utils/supabase/server'
import { revalidatePath } from 'next/cache'

export async function pullReport(reportId: string) {
  const supabase = createClient()
  
  // Reset to 'needs_revision' (Draft) and clear assignment
  const { error } = await supabase
    .from('demerit_reports')
    .update({ 
      status: 'needs_revision',
      current_approver_group_id: null 
    })
    .eq('id', reportId)

  if (error) {
    console.error('Pull Error:', error)
    return { success: false, error: error.message }
  }

  revalidatePath(`/report/${reportId}`)
  revalidatePath('/reports/submitted') // Refresh the list page too
  return { success: true }
}

